const $=s=>document.querySelector(s);
const cards=window.ATLAS_CARDS;
const colorMap={Red:'Vermelho',Green:'Verde',Blue:'Azul',Purple:'Roxo',Black:'Preto',Yellow:'Amarelo'};
const swatches={Vermelho:'#dc655c',Verde:'#70b68d',Azul:'#659ecb',Roxo:'#ac84cf',Preto:'#a3a9ac',Amarelo:'#e7c96c'};
const typeMap={LEADER:'Líder',CHARACTER:'Personagem',EVENT:'Evento',STAGE:'Cenário'};
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let favorites=[];try{favorites=JSON.parse(localStorage.getItem('atlas-favorites')||'[]');if(!Array.isArray(favorites))favorites=[];}catch{}
const colorsOf=c=>c.color.split('/').map(x=>colorMap[x]||x);
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2500);}
function renderCards(){const search=normalize($('#search').value.trim());const filtered=cards.filter(c=>(!search||normalize(c.name+' '+c.id+' '+c.archetype).includes(search))&&(!$('#color').value||colorsOf(c).includes($('#color').value))&&(!$('#type').value||c.type===$('#type').value)&&(!$('#rarity').value||c.rarity===$('#rarity').value)&&(!$('#favorites-only').checked||favorites.includes(c.id)));$('#result-count').textContent=filtered.length+' de '+cards.length+' cartas da amostra';$('#empty').hidden=filtered.length>0;$('#card-grid').innerHTML=filtered.map(c=>`<article class="col-6 col-md-4 col-lg-3 tcg-card"><button class="favorite-btn" data-favorite="${c.id}" aria-label="Favoritar ${escapeHtml(c.name)}" aria-pressed="${favorites.includes(c.id)}">${favorites.includes(c.id)?'♥':'♡'}</button><button class="card-picture" data-card="${c.id}" aria-label="Detalhes de ${escapeHtml(c.name)}"><img src="assets/${c.id}.png" loading="lazy" alt="${escapeHtml(c.name)} — ${c.id}"></button><div class="card-caption"><span>${c.id}</span><span class="rarity-badge">${c.rarity} · ${typeMap[c.type]}</span></div><h3 class="card-name">${escapeHtml(c.name)}</h3><div class="card-meta"><i class="color-dot" style="--card-color:${swatches[colorsOf(c)[0]]}"></i>${colorsOf(c).join(' / ')} <span>· ${escapeHtml(c.archetype.split('/').at(-1))}</span></div></article>`).join('');}
function resetFilters(){['search','color','type','rarity'].forEach(id=>$('#'+id).value='');$('#favorites-only').checked=false;renderCards();}
['search','color','type','rarity','favorites-only'].forEach(id=>$('#'+id).addEventListener('input',renderCards));$('#reset').onclick=resetFilters;$('#empty-reset').onclick=resetFilters;
document.addEventListener('click',e=>{const fav=e.target.closest('[data-favorite]');if(fav){const id=fav.dataset.favorite;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];try{localStorage.setItem('atlas-favorites',JSON.stringify(favorites));toast(favorites.includes(id)?'Carta salva neste navegador.':'Carta removida dos favoritos.');}catch{toast('Favorito disponível apenas nesta visita.');}renderCards();}const card=e.target.closest('[data-card]');if(card)openCard(card.dataset.card);const auth=e.target.closest('[data-auth]');if(auth)openAuth(auth.dataset.auth);});
function openCard(id){ location.href='carta.html?id='+encodeURIComponent(id); }
const colorInfo=[['Vermelho','Pressão desde o primeiro turno.','A cor costuma favorecer ataques e aumento de poder, com cartas que pressionam o adversário e podem reduzir o poder de personagens. A identidade do deck depende do líder e das cartas escolhidas.','ESTILO · AGRESSÃO E PODER'],['Verde','Controle o ritmo do campo.','Descansar personagens adversários e reativar os seus são temas recorrentes. A cor explora o estado ativo ou descansado das cartas para criar oportunidades.','ESTILO · CAMPO E TEMPO'],['Azul','Cada jogada muda a rota.','Retorno de cartas à mão ou ao deck, compra e manipulação do topo aparecem em diversas estratégias azuis. Planeje os próximos turnos e administre seus recursos.','ESTILO · RECURSOS E CONTROLE'],['Roxo','Mais DON!!, mais possibilidades.','Manipular DON!! é um tema frequente: acelerar recursos ou devolver DON!! ao deck como parte de efeitos. Equilibrar o ganho imediato com os turnos seguintes faz parte da estratégia.','ESTILO · DON!! E ACELERAÇÃO'],['Preto','O custo abre caminho.','Reduzir custos de personagens adversários e remover alvos dentro de certos limites de custo são temas comuns. Algumas estratégias também recuperam cartas do descarte.','ESTILO · CUSTO E REMOÇÃO'],['Amarelo','A vida também é um recurso.','Interações com cartas de vida e efeitos de Trigger marcam muitas estratégias amarelas. O texto de cada carta determina quando e como essas habilidades funcionam.','ESTILO · VIDA E TRIGGER']];
function selectColor(index){const info=colorInfo[index];document.querySelectorAll('.color-tab').forEach((t,i)=>{t.setAttribute('aria-selected',i===index);t.tabIndex=i===index?0:-1;});$('#color-detail').setAttribute('aria-labelledby','color-tab-'+index);$('#color-detail').innerHTML=`<div><small>${info[3]}</small><h3>${info[1]}</h3></div><p>${info[2]}<br><small>Tendências gerais; consulte sempre os efeitos e as regras oficiais.</small></p>`;}
$('.color-tabs').innerHTML=colorInfo.map((c,i)=>`<button class="color-tab" id="color-tab-${i}" role="tab" aria-controls="color-detail" aria-selected="${i===0}" tabindex="${i===0?0:-1}" style="--swatch:${swatches[c[0]]}" data-color-tab="${i}"><i></i>${c[0]}</button>`).join('');document.querySelectorAll('.color-tab').forEach((t,i)=>{t.onclick=()=>selectColor(i);t.onkeydown=e=>{let n=i;if(e.key==='ArrowRight')n=(i+1)%6;else if(e.key==='ArrowLeft')n=(i+5)%6;else if(e.key==='Home')n=0;else if(e.key==='End')n=5;else return;e.preventDefault();selectColor(n);$('#color-tab-'+n).focus();};});selectColor(0);
const glossary=[['Tipos de carta','Líder conduz o deck; Personagem atua no campo; Evento aplica seu efeito conforme as condições; Cenário permanece na área de cenários. DON!! é um recurso próprio do jogo.'],['Custo e poder','Custo indica o valor em DON!! necessário para jogar uma carta, salvo efeitos. Poder é usado nas batalhas. No lugar de custo, líderes exibem sua vida inicial.'],['Atributo','Strike, Slash, Ranged, Special e Wisdom são atributos que podem ser referenciados por efeitos. Atributo é diferente de cor e de tipo de personagem.'],['Raridade e versões','C, UC, R, SR, SEC e L identificam categorias impressas. Uma arte alternativa é uma versão de impressão; não deve ser confundida com um novo ID de carta.'],['Counter (contador)','O Counter impresso de um Personagem pode aumentar o poder do seu Líder ou Personagem durante a etapa de defesa ao descartar aquela carta da mão, conforme as regras. Eventos de Counter têm seus próprios custos e efeitos.'],['Blocker (bloquear)','Quando ativado nas condições indicadas, permite descansar o Personagem com Blocker e mudar para ele o alvo do ataque. Consulte as exceções e o texto de cada carta.'],['Palavras-chave','Rush, Blocker, Double Attack e Banish são exemplos. Palavras-chave resumem regras de habilidades; indicadores como On Play e When Attacking indicam momentos de ativação.'],['Arquétipo e características','Um arquétipo é uma estratégia organizada em torno de um líder ou sinergia. Características como Straw Hat Crew e Supernovas são dados impressos na carta e podem ser exigidas por efeitos.'],['Bloco ≠ Blocker','O ícone de bloco identifica um agrupamento de cartas para as regras dos formatos que o utilizam. Não é uma habilidade de bloquear e não substitui a consulta à legalidade atual.']];
$('#glossary').innerHTML=glossary.map(([t,p])=>`<div class="col-12 col-md-6 col-lg-4"><details><summary>${t}</summary><p>${p}</p></details></div>`).join('');
$('.manga-wall').innerHTML=Array.from({length:5},(_,i)=>`<div class="manga-column">${Array.from({length:6},(_,j)=>`<img src="assets/cover-${(i*2+j)%12}.jpg" alt="" fetchpriority="low">`).join('')}</div>`).join('');
let authMode='login';function openAuth(mode){authMode=mode;updateAuth();$('#auth-dialog').showModal();}function updateAuth(){const signup=authMode==='signup';$('#auth-form').reset();$('#auth-status').textContent='';$('#name-field').hidden=!signup;$('#auth-name').required=signup;$('#auth-form input[type=password]').autocomplete=signup?'new-password':'current-password';$('#auth-title').textContent=signup?'Embarque nessa jornada.':'Sua próxima aventura.';$('#auth-intro').textContent=signup?'Crie seu perfil de explorador do Atlas.':'Entre para continuar sua jornada no Atlas.';$('#auth-submit').textContent=signup?'Criar minha conta ↗':'Entrar no Atlas ↗';$('#auth-switch').textContent=signup?'Já faz parte da tripulação? Entrar':'Ainda não embarcou? Criar uma conta';}$('#auth-switch').onclick=()=>{authMode=authMode==='signup'?'login':'signup';updateAuth();};$('#auth-form').onsubmit=e=>{e.preventDefault();$('#auth-status').textContent='Interface validada. A autenticação real será implementada com sessões PHP e MySQL.';$('#auth-form input[type=password]').value='';};
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.dialog-close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){const b=d.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)d.close();}});d.addEventListener('close',()=>{if(d.id==='auth-dialog'){$('#auth-form').reset();$('#auth-status').textContent='';}});});
$('.menu-toggle').onclick=()=>{const open=$('nav').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',open);};document.querySelectorAll('nav a').forEach(a=>a.onclick=()=>{$('nav').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('#search').focus();}});
const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+entry.target.id));}});},{rootMargin:'-10% 0px -65% 0px'});document.querySelectorAll('main section[id]').forEach(s=>observer.observe(s));renderCards();
